237	    /**
238	     * Enforces that the national portion of an E.164 number has the exact number of digits its
239	     * country code requires.
240	     *
241	     * @param national the national-number digits (the part after the country code)
242	     * @param expected the exact national-number length the country code requires
243	     * @param countryCode the country code, for the error message
244	     * @throws InvalidTelephoneException if {@code national} does not have exactly {@code expected} digits
245	     */
246	    private static void requireNationalLength(String national, int expected, String countryCode) {
247	        if (national.length() != expected) {
248	            throw new InvalidTelephoneException(
249	                "Telephone with country code '" + countryCode + "' must have " + expected
250	                    + " national digits");
251	        }
252	    }
