254	    /**
255	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
256	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
257	     *
258	     * @param email the raw email as supplied by the caller, may be {@code null}
259	     * @return the lower-cased email, or {@code null} when none was supplied
260	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
261	     */
262	    private static String normalizeEmail(String email) {
263	        if (email == null || email.isBlank()) {
264	            return null;
265	        }
266	        String trimmed = email.trim();
267	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
268	            throw new InvalidEmailException("Email must be a syntactically valid address");
269	        }
270	        String lowerCased = trimmed.toLowerCase(Locale.ROOT);
271	        String domain = lowerCased.substring(lowerCased.indexOf('@') + 1);
272	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
273	            throw new InvalidEmailException("Email domain is not allowed");
274	        }
275	        return lowerCased;
276	    }
