278	    /**
279	     * Derives the single duplicate-detection key that consolidates the former separate telephone,
280	     * email and household checks. The key is {@code normalizedTelephone + '|' + email + '|' +
281	     * householdId}, where the email segment is the empty string when the owner has no email. Because
282	     * the telephone is part of the key, two owners that differ in any one segment (for example two
283	     * members of the same household with different telephones) produce different keys.
284	     *
285	     * @param normalizedTelephone the E.164 telephone of the owner
286	     * @param email the lower-cased email of the owner, may be {@code null}
287	     * @param householdId the stable household identifier of the owner, may be {@code null}
288	     * @return the derived identity key
289	     */
290	    private static String deriveIdentityKey(String normalizedTelephone, String email, String householdId) {
291	        return (normalizedTelephone == null ? "" : normalizedTelephone)
292	            + "|" + (email == null ? "" : email)
293	            + "|" + (householdId == null ? "" : householdId);
294	    }
