296	    /**
297	     * Rejects a create only when the new owner's whole {@code identityKey} equals that of an existing
298	     * owner. This one check replaces the former separate telephone, email and household duplicate
299	     * checks: only an exact full-key match is a duplicate, so two owners that differ in any single
300	     * segment are both allowed. Each existing owner's key is derived from its stored, already
301	     * normalized telephone, email and household identifier.
302	     *
303	     * @param identityKey the derived identity key of the owner being created
304	     * @throws DuplicateIdentityException if another owner already has this identity key
305	     */
306	    private void rejectDuplicateIdentity(String identityKey) {
307	        boolean inUse = this.clinicService.findAllOwners().stream()
308	            .anyMatch(existing -> identityKey.equals(
309	                deriveIdentityKey(existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
310	        if (inUse) {
311	            throw new DuplicateIdentityException(
312	                "An owner with the same identity key already exists");
313	        }
314	    }
