316	    /**
317	     * Rejects a create when an existing owner already belongs to the same household (i.e. carries the
318	     * same computed {@code householdId}, derived from last name and postcode), unless the request
319	     * knowingly opts in via {@code sharesHousehold}. Setting {@code sharesHousehold} bypasses this
320	     * block so the owner is created as a declared member of the existing household; without it, a
321	     * second owner in the same household is a conflict.
322	     *
323	     * @param householdId the computed household identifier of the owner being created
324	     * @param sharesHousehold whether the request opted in to sharing an existing household
325	     * @throws DuplicateHouseholdException if the household already exists and the request did not opt in
326	     */
327	    private void rejectDuplicateHousehold(String householdId, boolean sharesHousehold) {
328	        if (sharesHousehold) {
329	            return;
330	        }
331	        boolean exists = this.clinicService.findAllOwners().stream()
332	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
333	        if (exists) {
334	            throw new DuplicateHouseholdException(
335	                "An owner with the same last name and postcode already exists");
336	        }
337	    }
