339	    /**
340	     * Finds a soft-match "possible duplicate" for the owner being created: an existing owner that is
341	     * not a hard identity duplicate but shares this owner's last name (compared case-insensitively) and
342	     * postcode while carrying a different telephone. When the postcode is absent no owner can share it,
343	     * so there is never a match. When several existing owners qualify the one with the lowest id is
344	     * returned, so the result is deterministic.
345	     *
346	     * @param lastName the last name of the owner being created
347	     * @param postcode the postcode of the owner being created, may be {@code null}
348	     * @param normalizedTelephone the E.164 telephone of the owner being created
349	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
350	     */
351	    private Integer findPossibleDuplicateOf(String lastName, String postcode, String normalizedTelephone) {
352	        if (postcode == null || postcode.isBlank()) {
353	            return null;
354	        }
355	        String normalizedLastName = normalizeName(lastName);
356	        return this.clinicService.findAllOwners().stream()
357	            .filter(existing -> normalizedLastName.equals(normalizeName(existing.getLastName())))
358	            .filter(existing -> postcode.equals(existing.getPostcode()))
359	            .filter(existing -> !normalizedTelephone.equals(existing.getTelephone()))
360	            .map(Owner::getId)
361	            .filter(java.util.Objects::nonNull)
362	            .min(Integer::compareTo)
363	            .orElse(null);
364	    }
