383	    /**
384	     * The maximum number of owners a single city may contain. A create whose city already holds this
385	     * many owners is rejected, so a city never grows beyond this capacity.
386	     */
387	    private static final int CITY_CAPACITY = 50;
388	
389	    /**
390	     * Rejects a create whose city already contains {@link #CITY_CAPACITY} or more owners, so no city
391	     * ever exceeds its capacity. Cities are compared case-insensitively with surrounding whitespace
392	     * trimmed. The count reflects the
393	     * state before the new owner is persisted, so it excludes the owner being created.
394	     *
395	     * @param city the city of the owner being created
396	     * @throws CityAtCapacityException if the city already contains {@link #CITY_CAPACITY} owners
397	     */
398	    private void rejectCityAtCapacity(String city) {
399	        String normalizedCity = normalizeName(city);
400	        long ownersInCity = this.clinicService.findAllOwners().stream()
401	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
402	            .count();
403	        if (ownersInCity >= CITY_CAPACITY) {
404	            throw new CityAtCapacityException(
405	                "The city already contains the maximum number of owners");
406	        }
