409	    /**
410	     * The maximum number of owners that may be created on a single day. A create made once this many
411	     * owners already carry today's {@code registrationDate} is rejected, so no more than this many
412	     * owners are registered per day.
413	     */
414	    private static final int DAILY_OWNER_LIMIT = 100;
415	
416	    /**
417	     * Rejects a create once {@link #DAILY_OWNER_LIMIT} or more owners have already been created for
418	     * the given business day, counted by {@code registrationDate} equal to the effective (weekend
419	     * rolled forward) registration date of the owner being created. The count reflects the state
420	     * before the new owner is persisted, so it excludes the owner being created.
421	     *
422	     * @param registrationDate the effective business-day registration date of the owner being created
423	     * @throws DailyOwnerLimitExceededException if the day already holds {@link #DAILY_OWNER_LIMIT} owners
424	     */
425	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
426	        long ownersToday = this.clinicService.findAllOwners().stream()
427	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
428	            .count();
429	        if (ownersToday >= DAILY_OWNER_LIMIT) {
430	            throw new DailyOwnerLimitExceededException(
431	                "The maximum number of owners for today has already been reached");
432	        }
433	    }
