435	    /**
436	     * The number of owners that may already exist for a business day before a create is flagged with
437	     * a bulk-signup warning. Once more than this many owners already carry the effective registration
438	     * date, the created owner's {@code bulkSignupWarning} is set to {@code true}.
439	     */
440	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
441	
442	    /**
443	     * Determines whether a create should be flagged with a bulk-signup warning, i.e. whether more than
444	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for the given business day,
445	     * counted by {@code registrationDate} equal to the effective (weekend rolled forward) registration
446	     * date of the owner being created. The count reflects the state before the new owner is persisted,
447	     * so it excludes the owner being created.
448	     *
449	     * @param registrationDate the effective business-day registration date of the owner being created
450	     * @return {@code true} when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the date
451	     */
452	    private boolean bulkSignupWarning(LocalDate registrationDate) {
453	        long ownersToday = this.clinicService.findAllOwners().stream()
454	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
455	            .count();
456	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
457	    }
