459	    /**
460	     * Rolls a registration date forward to a business day: a Saturday or Sunday is advanced to the
461	     * following Monday, any weekday is returned unchanged.
462	     *
463	     * @param date the effective registration date, supplied or defaulted to the server date
464	     * @return the same date when it is a weekday, otherwise the next Monday
465	     */
466	    private static LocalDate toBusinessDay(LocalDate date) {
467	        DayOfWeek dayOfWeek = date.getDayOfWeek();
468	        if (dayOfWeek == DayOfWeek.SATURDAY) {
469	            return date.plusDays(2);
470	        }
471	        if (dayOfWeek == DayOfWeek.SUNDAY) {
472	            return date.plusDays(1);
473	        }
474	        return date;
475	    }
