477	    /**
478	     * Builds the customer code assigned to an owner on create, formatted {@code '<REGION>-<HASH8>'}
479	     * where {@code REGION} is the region code derived from the owner's postcode (the region whose
480	     * inclusive range contains the postcode, or {@code 'UNKNOWN'} when the postcode is absent or in
481	     * no known range) and {@code HASH8} is the first eight upper-cased hex characters of the SHA-256
482	     * of {@code normalizedTelephone + lastName}, e.g. {@code 'NSW-1A2B3C4D'}. There is no sequence
483	     * component: the identity is a pure region-and-hash value.
484	     *
485	     * @param postcode the postcode of the owner being created, may be {@code null}
486	     * @param normalizedTelephone the E.164 telephone of the owner being created
487	     * @param lastName the last name of the owner being created
488	     * @return the formatted customer code
489	     */
490	    private String customerCode(String postcode, String normalizedTelephone, String lastName) {
491	        return regionFromPostcode(postcode) + "-" + sha256HexPrefix(normalizedTelephone + lastName, 8);
492	    }
493	
494	    /**
495	     * De-duplicates a freshly computed customer code against the customer codes already held by
496	     * existing owners. When the code is unused it is returned unchanged; otherwise {@code '-<n>'} is
497	     * appended with the smallest {@code n} of 2 or more that yields a code no existing owner carries.
498	     *
499	     * @param customerCode the computed customer code for the owner being created
500	     * @return the same code when unique, otherwise the code with a {@code '-<n>'} suffix that makes
501	     *     it unique
502	     */
503	    private String deduplicateCustomerCode(String customerCode) {
504	        Set<String> existing = new java.util.HashSet<>();
505	        for (Owner owner : this.clinicService.findAllOwners()) {
506	            if (owner.getCustomerCode() != null) {
507	                existing.add(owner.getCustomerCode());
508	            }
509	        }
510	        if (!existing.contains(customerCode)) {
511	            return customerCode;
512	        }
513	        int n = 2;
514	        while (existing.contains(customerCode + "-" + n)) {
515	            n++;
516	        }
517	        return customerCode + "-" + n;
518	    }
519	
520	    /**
521	     * Returns the region code whose inclusive postcode range contains the given 4-digit postcode
522	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code 'UNKNOWN'} when the postcode is
523	     * {@code null}, non-numeric, or in no known range.
524	     *
525	     * @param postcode the postcode, may be {@code null}
526	     * @return the region code, or {@code 'UNKNOWN'}
527	     */
528	    private static String regionFromPostcode(String postcode) {
529	        if (postcode == null || postcode.isBlank()) {
530	            return "UNKNOWN";
531	        }
532	        int code;
533	        try {
534	            code = Integer.parseInt(postcode.trim());
535	        } catch (NumberFormatException e) {
536	            return "UNKNOWN";
537	        }
538	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
539	            int[] range = entry.getValue();
540	            if (code >= range[0] && code <= range[1]) {
541	                return entry.getKey();
542	            }
543	        }
544	        return "UNKNOWN";
545	    }
546	
547	    /**
548	     * Computes the SHA-256 of {@code value} and returns its first {@code length} hex characters,
549	     * upper-cased.
550	     *
551	     * @param value the string to hash
552	     * @param length the number of leading hex characters to return
553	     * @return the upper-cased hex prefix of the digest
554	     */
555	    private static String sha256HexPrefix(String value, int length) {
556	        try {
557	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
558	            StringBuilder sb = new StringBuilder(digest.length * 2);
559	            for (byte b : digest) {
560	                sb.append(String.format("%02x", b));
561	            }
562	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
563	        } catch (NoSuchAlgorithmException e) {
564	            throw new IllegalStateException("SHA-256 not available", e);
565	        }
566	    }
