568	    /**
569	     * Counts the existing owners that share the owner-to-be's first and last name, compared
570	     * case-insensitively (surrounding whitespace trimmed). The count reflects the state before the
571	     * new owner is persisted, so it excludes the owner being created.
572	     *
573	     * @param firstName the first name of the owner being created
574	     * @param lastName the last name of the owner being created
575	     * @return the number of existing owners with the same first and last name
576	     */
577	    private int countNamesakes(String firstName, String lastName) {
578	        String normalizedFirstName = normalizeName(firstName);
579	        String normalizedLastName = normalizeName(lastName);
580	        return (int) this.clinicService.findAllOwners().stream()
581	            .filter(existing ->
582	                normalizedFirstName.equals(normalizeName(existing.getFirstName()))
583	                    && normalizedLastName.equals(normalizeName(existing.getLastName())))
584	            .count();
585	    }
