587	    /**
588	     * Counts the members of the owner-to-be's household after this create, i.e. one more than the
589	     * number of existing owners already carrying the same {@code householdId}. The household
590	     * identifier is a deterministic function of last name and postcode, so a solo owner (the only one
591	     * with that identifier) is a household of one. The count includes the owner being created (hence
592	     * the {@code + 1}).
593	     *
594	     * @param householdId the stable household identifier of the owner being created
595	     * @return the number of household members after this create (always at least 1)
596	     */
597	    private int householdSize(String householdId) {
598	        if (householdId == null) {
599	            return 1;
600	        }
601	        return (int) this.clinicService.findAllOwners().stream()
602	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
603	            .count() + 1;
604	    }
