606	    /**
607	     * Normalizes a name for case-insensitive comparison by trimming surrounding whitespace and
608	     * lower-casing.
609	     *
610	     * @param value the raw name, may be {@code null}
611	     * @return the normalized name ({@code ""} when {@code value} is {@code null})
612	     */
613	    private static String normalizeName(String value) {
614	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
615	    }
