617	    /**
618	     * The fixed city-to-region table used to validate a postcode against its city
619	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). A city not in this table has no known region and
620	     * therefore accepts any 4-digit postcode.
621	     */
622	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
623	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
624	
625	    /**
626	     * The fixed region-to-postcode-range table: each region admits an inclusive 4-digit range
627	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
628	     */
629	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
630	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
631	
632	    /**
633	     * Validates an owner's optional postcode on create. A {@code null} or blank postcode is left
634	     * untouched (postcode is optional when absent). When present it must be exactly four digits and,
635	     * when the city maps to a known region, must fall within that region's inclusive range
636	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
637	     * postcode.
638	     *
639	     * @param city the city of the owner being created
640	     * @param postcode the raw postcode as supplied by the caller, may be {@code null}
641	     * @throws InvalidPostcodeException if a present postcode is not four digits or is out of range
642	     *     for the city's region
643	     */
644	    private static void validatePostcode(String city, String postcode) {
645	        if (postcode == null || postcode.isBlank()) {
646	            return;
647	        }
648	        if (!postcode.matches("\\d{4}")) {
649	            throw new InvalidPostcodeException("Postcode must be exactly 4 digits");
650	        }
651	        String region = CITY_REGION.get(city);
652	        int[] range = region == null ? null : REGION_POSTCODES.get(region);
653	        if (range != null) {
654	            int value = Integer.parseInt(postcode);
655	            if (value < range[0] || value > range[1]) {
656	                throw new InvalidPostcodeException(
657	                    "Postcode is out of range for the city's region");
658	            }
659	        }
660	    }
