672	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
673	    @Override
674	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
675	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
676	        validateRequiredFields(ownerFieldsDto);
677	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
678	        if (registrationDate == null) {
679	            registrationDate = LocalDate.now();
680	        } else if (registrationDate.isAfter(LocalDate.now())) {
681	            throw new FutureRegistrationDateException(
682	                "registrationDate must not be later than the server date");
683	        }
684	        registrationDate = toBusinessDay(registrationDate);
685	        ownerFieldsDto.setRegistrationDate(registrationDate);
686	        rejectDailyOwnerLimit(registrationDate);
687	        rejectCityAtCapacity(ownerFieldsDto.getCity());
688	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
689	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
690	        ownerFieldsDto.setTelephone(normalizedTelephone);
691	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
692	        ownerFieldsDto.setEmail(normalizedEmail);
693	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
694	        String ownerHouseholdId = householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
695	        rejectDuplicateIdentity(deriveIdentityKey(normalizedTelephone, normalizedEmail, ownerHouseholdId));
696	        rejectDuplicateHousehold(ownerHouseholdId, sharesHousehold);
697	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicateOf(
698	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode(), normalizedTelephone);
699	        HttpHeaders headers = new HttpHeaders();
700	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
701	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
702	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
703	        owner.setCustomerCode(deduplicateCustomerCode(customerCode(
704	            ownerFieldsDto.getPostcode(), normalizedTelephone, ownerFieldsDto.getLastName())));
705	        owner.setHouseholdId(ownerHouseholdId);
706	        owner.setHouseholdSize(householdSize(ownerHouseholdId));
707	        owner.setNamesakeCount(countNamesakes(ownerFieldsDto.getFirstName(), ownerFieldsDto.getLastName()));
708	        owner.setBulkSignupWarning(bulkSignupWarning(registrationDate));
709	        this.clinicService.saveOwner(owner);
710	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
711	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
712	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
713	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
714	        headers.setLocation(UriComponentsBuilder.newInstance()
715	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
716	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
717	    }
