719	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
720	    @Override
721	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
722	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
723	        if (currentOwner == null) {
724	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
725	        }
726	        currentOwner.setAddress(ownerFieldsDto.getAddress());
727	        currentOwner.setCity(ownerFieldsDto.getCity());
728	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
729	        currentOwner.setLastName(ownerFieldsDto.getLastName());
730	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
731	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
732	        this.clinicService.saveOwner(currentOwner);
733	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
734	    }
735	
736	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
737	    @Transactional
738	    @Override
739	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
740	        Owner owner = this.clinicService.findOwnerById(ownerId);
741	        if (owner == null) {
742	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
743	        }
744	        this.clinicService.deleteOwner(owner);
745	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
746	    }
747	
748	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
749	    @Override
750	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
751	        Owner owner = this.clinicService.findOwnerById(ownerId);
752	        if (owner == null) {
753	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
754	        }
755	        HttpHeaders headers = new HttpHeaders();
756	        Pet pet = petMapper.toPet(petFieldsDto);
757	        owner.setId(ownerId);
758	        pet.setOwner(owner);
759	        pet.getType().setName(null);
760	        this.clinicService.savePet(pet);
761	        PetDto petDto = petMapper.toPetDto(pet);
762	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
763	            .buildAndExpand(pet.getId()).toUri());
764	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
765	    }
766	
767	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
768	    @Override
769	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
770	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
771	        if (currentOwner != null) {
772	            Pet currentPet = this.clinicService.findPetById(petId);
773	            if (currentPet != null) {
774	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
775	                currentPet.setName(petFieldsDto.getName());
776	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
777	                this.clinicService.savePet(currentPet);
778	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
779	            }
780	        }
781	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
782	    }
783	
784	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
785	    @Override
786	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
787	        HttpHeaders headers = new HttpHeaders();
788	        Visit visit = visitMapper.toVisit(visitFieldsDto);
789	        Pet pet = new Pet();
790	        pet.setId(petId);
791	        visit.setPet(pet);
792	        this.clinicService.saveVisit(visit);
793	        VisitDto visitDto = visitMapper.toVisitDto(visit);
794	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
795	            .buildAndExpand(visit.getId()).toUri());
796	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
797	    }
798	
799	
800	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
801	    @Override
802	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
803	        Owner owner = this.clinicService.findOwnerById(ownerId);
804	        if (owner != null) {
805	            Pet pet = owner.getPet(petId);
806	            if (pet != null) {
807	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
808	            }
809	        }
810	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
811	    }
812	}
