37	     * Derives the owner's {@code ageBand} from its birthDate relative to the registrationDate:
38	     * {@code MINOR} when under 18, {@code ADULT} when 18 to 64, and {@code SENIOR} when 65 or older.
39	     * Returns {@code null} when the owner has no birthDate or no registrationDate.
40	     */
41	    default OwnerDto.@Nullable AgeBandEnum ageBand(@Nullable Owner owner) {
42	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
