65	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
66	        String email = owner.getEmail() == null ? "" : owner.getEmail();
67	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
68	        return telephone + "|" + email + "|" + householdId;
69	    }
70	
71	    /**
72	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email is present,
73	     * otherwise {@code PHONE}.
74	     */
75	    default OwnerDto.@Nullable ContactPreferenceEnum contactPreference(@Nullable Owner owner) {
76	        if (owner == null) {
77	            return null;
78	        }
79	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
80	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
81	    }
82	
83	    /**
84	     * Derives the owner's locality from its region-and-hash identity: the {@code REGION} prefix of
85	     * the {@code customerCode} ({@code '<REGION>-<HASH8>'}), which is the region code derived from
86	     * the postcode on create. Returns the canonical region string, or {@code 'UNKNOWN'} when the
87	     * owner has no customerCode.
88	     */
89	    default @Nullable String locality(@Nullable Owner owner) {
90	        if (owner == null) {
91	            return null;
92	        }
93	        String customerCode = owner.getCustomerCode();
94	        if (customerCode == null) {
95	            return "UNKNOWN";
96	        }
