103	     * region-to-timezone table: {@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
104	     * and {@code QLD -> Australia/Brisbane}. Returns {@code null} when the region is not in the table.
105	     */
106	    default @Nullable String timezone(@Nullable Owner owner) {
107	        String region = locality(owner);
108	        if (region == null) {
109	            return null;
110	        }
111	        return switch (region) {
112	            case "NSW" -> "Australia/Sydney";
113	            case "VIC" -> "Australia/Melbourne";
114	            case "QLD" -> "Australia/Brisbane";
115	            default -> null;
116	        };
117	    }
118	
119	    /**
120	     * Returns the owner's membership points. Starting at 0, it adds 2 when an email is present, 1
121	     * when namesakeCount is 0, 2 when the owner belongs to a household of at least 3 members, and 3
122	     * when tenure exceeds 365 days since the registrationDate. Because a newly created owner has zero
123	     * tenure it never earns the tenure points.
124	     */
125	    default @Nullable Integer membershipPoints(@Nullable Owner owner) {
126	        if (owner == null) {
127	            return null;
128	        }
129	        int points = 0;
130	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
131	        if (hasEmail) {
132	            points += 2;
133	        }
134	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
135	        if (noNamesakes) {
136	            points += 1;
137	        }
138	        boolean largeHousehold = owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
139	        if (largeHousehold) {
140	            points += 2;
141	        }
142	        if (hasQualifyingTenure(owner)) {
143	            points += 3;
144	        }
145	        return points;
146	    }
147	
148	    /**
149	     * Returns the owner's numeric membership level from 1 to 4, derived from membershipPoints:
150	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more points.
151	     */
152	    default @Nullable Integer membershipLevel(@Nullable Owner owner) {
153	        Integer points = membershipPoints(owner);
154	        if (points == null) {
155	            return null;
156	        }
157	        if (points <= 1) {
158	            return 1;
159	        }
160	        if (points <= 3) {
161	            return 2;
162	        }
163	        if (points <= 5) {
164	            return 3;
165	        }
166	        return 4;
167	    }
